<?php
require __DIR__ . '/config.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
$stmt=$pdo->prepare("SELECT * FROM students WHERE id=?"); $stmt->execute([$id]); $s=$stmt->fetch();
if (!$s) { flash('Student record not found.','error'); redirect('index.php'); }
$stmt=$pdo->prepare("SELECT * FROM student_files WHERE student_id=? ORDER BY uploaded_at DESC"); $stmt->execute([$id]); $files=$stmt->fetchAll();
$flash=$_SESSION['flash']??null; unset($_SESSION['flash']);
?>
